import{S as e,h as t,m as n,t as r}from"./app-BvXTZrcI.js";var i=JSON.parse(`{"path":"/guide/resty/","title":"HTTP-клиент на Resty","lang":"ru-RU","frontmatter":{"prev":"/guide/http-client/best-practices.md","next":"/guide/resty/tests.md"},"git":{"updatedTime":1792442946000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"20a948be9028fe626c444056e84191214ea24ecd","time":1792442946000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"fix: improved contrast"}]},"filePathRelative":"guide/resty/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="http-клиент-на-resty" tabindex="-1"><a class="header-anchor" href="#http-клиент-на-resty"><span>HTTP-клиент на Resty</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Переписать клиент подсказок приоритета на Resty и сравнить его со стандартным <code>http.Client</code>. Научиться настраивать base URL, заголовки, context, JSON-декодирование, обработку HTTP-статусов, ограниченный retry и тестировать Resty-клиент через <code>httptest.Server</code> без изменения интерфейса service.</p><p>Resty — сторонняя библиотека для HTTP-клиента. Она использует <code>net/http</code> под капотом, но сокращает повторяющийся код для query-параметров, заголовков, JSON и retry. Она не отменяет знания предыдущей главы: статусы, context, таймауты, безопасность данных и HTTP-контракт всё равно остаются ответственностью разработчика.</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">TaskService → PrioritySuggester → Resty → net/http → внешний API</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Как и Gin, Resty должен оставаться на границе приложения. <code>TaskService</code> зависит от интерфейса <code>PrioritySuggester</code>, а не от Resty.</p><h2 id="установка" tabindex="-1"><a class="header-anchor" href="#установка"><span>Установка</span></a></h2><p>В корне Task Manager API выполните:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go get github.com/go-resty/resty/v2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Импорт пакета:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">import</span> <span class="token string">&quot;github.com/go-resty/resty/v2&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Go добавит прямую зависимость в <code>go.mod</code>, а Resty и требуемые ей модули — в <code>go.sum</code>. Не редактируйте их вручную. После добавления запустите:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go <span class="token builtin class-name">test</span> ./<span class="token punctuation">..</span>.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="сравнение-с-http-client" tabindex="-1"><a class="header-anchor" href="#сравнение-с-http-client"><span>Сравнение с <code>http.Client</code></span></a></h2><p>В предыдущей главе базовый вызов выглядел так:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">request<span class="token punctuation">,</span> err <span class="token operator">:=</span> http<span class="token punctuation">.</span><span class="token function">NewRequestWithContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> http<span class="token punctuation">.</span>MethodGet<span class="token punctuation">,</span> endpoint<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">request<span class="token punctuation">.</span>Header<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Accept&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> httpClient<span class="token punctuation">.</span><span class="token function">Do</span><span class="token punctuation">(</span>request<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">defer</span> response<span class="token punctuation">.</span>Body<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> response<span class="token punctuation">.</span>StatusCode <span class="token operator">&lt;</span> <span class="token number">200</span> <span class="token operator">||</span> response<span class="token punctuation">.</span>StatusCode <span class="token operator">&gt;=</span> <span class="token number">300</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>HTTPStatusError<span class="token punctuation">{</span><span class="token operator">...</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">var</span> hint PriorityHint</span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">NewDecoder</span><span class="token punctuation">(</span>response<span class="token punctuation">.</span>Body<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Decode</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>hint<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Resty делает тот же запрос компактнее:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">var</span> hint PriorityHint</span>
<span class="line"></span>
<span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">R</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetQueryParam</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">,</span> title<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetResult</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>hint<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> response<span class="token punctuation">.</span><span class="token function">IsError</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>HTTPStatusError<span class="token punctuation">{</span></span>
<span class="line">		StatusCode<span class="token punctuation">:</span> response<span class="token punctuation">.</span><span class="token function">StatusCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">		Status<span class="token punctuation">:</span>     response<span class="token punctuation">.</span><span class="token function">Status</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>SetResult</code> автоматически декодирует JSON или XML для успешного статуса <code>2xx</code>, если сервер указал подходящий <code>Content-Type</code>. Но Resty не выбирает за вас политику статусов, проверки значений или публичную обработку ошибок.</p><h2 id="настроика-resty-клиента" tabindex="-1"><a class="header-anchor" href="#настроика-resty-клиента"><span>Настройка Resty-клиента</span></a></h2><p>Как и <code>http.Client</code>, экземпляр Resty создают один раз и передают как зависимость. Настройте base URL, общий timeout и заголовки в конструкторе:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> Client <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	resty <span class="token operator">*</span>resty<span class="token punctuation">.</span>Client</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">New</span><span class="token punctuation">(</span>baseURL <span class="token builtin">string</span><span class="token punctuation">,</span> transport http<span class="token punctuation">.</span>RoundTripper<span class="token punctuation">)</span> <span class="token operator">*</span>Client <span class="token punctuation">{</span></span>
<span class="line">	client <span class="token operator">:=</span> resty<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">		<span class="token function">SetBaseURL</span><span class="token punctuation">(</span>strings<span class="token punctuation">.</span><span class="token function">TrimRight</span><span class="token punctuation">(</span>baseURL<span class="token punctuation">,</span> <span class="token string">&quot;/&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">		<span class="token function">SetTimeout</span><span class="token punctuation">(</span><span class="token number">3</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">		<span class="token function">SetHeader</span><span class="token punctuation">(</span><span class="token string">&quot;Accept&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">		<span class="token function">SetHeader</span><span class="token punctuation">(</span><span class="token string">&quot;User-Agent&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;task-manager-api/1.0&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> transport <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		client<span class="token punctuation">.</span><span class="token function">SetTransport</span><span class="token punctuation">(</span>transport<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> <span class="token operator">&amp;</span>Client<span class="token punctuation">{</span>resty<span class="token punctuation">:</span> client<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В production чаще достаточно <code>resty.New()</code> и настроек Resty. Если программе нужен специально настроенный транспорт (proxy, TLS, собственный <code>RoundTripper</code>), передайте его явно и проверьте контракт тестами. <code>httptest.Server</code> предоставляет совместимый транспорт как <code>server.Client().Transport</code>.</p><div class="hint-container warning"><p class="hint-container-title">Не смешивайте ответственность клиентов</p><p><code>resty.Client.SetTimeout</code> задаёт общий таймаут Resty. Не нужно одновременно создавать новый <code>http.Client</code> с другим timeout на каждый запрос. Для отдельной операции используйте <code>SetContext</code> с дочерним context и <code>defer cancel()</code>.</p></div><h2 id="query-параметры-и-заголовки" tabindex="-1"><a class="header-anchor" href="#query-параметры-и-заголовки"><span>Query-параметры и заголовки</span></a></h2><p>Resty сам кодирует query-параметры:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">R</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetQueryParam</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">,</span> title<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для нескольких параметров используйте <code>SetQueryParams</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token function">SetQueryParams</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span></span>
<span class="line">	<span class="token string">&quot;title&quot;</span><span class="token punctuation">:</span>  title<span class="token punctuation">,</span></span>
<span class="line">	<span class="token string">&quot;locale&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;ru-RU&quot;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Общие заголовки задают в конструкторе. Заголовок конкретного запроса добавляют через <code>SetHeader</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">R</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetHeader</span><span class="token punctuation">(</span><span class="token string">&quot;X-Request-ID&quot;</span><span class="token punctuation">,</span> requestID<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Токены и пароли берите из конфигурации. Никогда не логируйте <code>Authorization</code>, cookies и body запроса целиком.</p><h2 id="context-и-отмена" tabindex="-1"><a class="header-anchor" href="#context-и-отмена"><span>Context и отмена</span></a></h2><p>Resty не заменяет <code>context.Context</code>. Передайте context у конкретного запроса:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">R</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetQueryParam</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">,</span> title<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В Gin handler исходный context приходит из <code>c.Request.Context()</code>. Service передаёт его в <code>PrioritySuggester</code>, а реализация Resty вызывает <code>SetContext(ctx)</code>. Так отмена клиента и дедлайн распространяются от HTTP handler к внешнему API.</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">c.Request.Context() → TaskService → PrioritySuggester.Suggest → Request.SetContext</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Не используйте <code>context.Background()</code> внутри метода <code>Suggest</code>: это оборвёт цепочку отмены.</p><h2 id="json-request-и-response" tabindex="-1"><a class="header-anchor" href="#json-request-и-response"><span>JSON request и response</span></a></h2><p>Для <code>GET</code> подсказки нужен только query. Если внешний API принимает JSON, Resty сериализует структуру через <code>SetBody</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">request <span class="token operator">:=</span> <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	Title <span class="token builtin">string</span> <span class="token string">\`json:&quot;title&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">{</span>Title<span class="token punctuation">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">R</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetHeader</span><span class="token punctuation">(</span><span class="token string">&quot;Content-Type&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetBody</span><span class="token punctuation">(</span>request<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetResult</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>hint<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">Post</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для текущего GET-запроса ответ декодируется через <code>SetResult</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">var</span> hint PriorityHint</span>
<span class="line"></span>
<span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">R</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetQueryParam</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">,</span> title<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetResult</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>hint<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Не декодируйте внешний ответ в <code>task.Task</code>. <code>PriorityHint</code> остаётся отдельным DTO, а service решает, как применить его к правилам создания задачи.</p><h2 id="полная-реализация-suggest" tabindex="-1"><a class="header-anchor" href="#полная-реализация-suggest"><span>Полная реализация <code>Suggest</code></span></a></h2><p>Сохраним контракт предыдущей главы: service получает <code>PriorityHint</code>, а не знает, какая библиотека выполняет запрос.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> PriorityHint <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	Priority <span class="token builtin">int</span>    <span class="token string">\`json:&quot;priority&quot;\`</span></span>
<span class="line">	Source   <span class="token builtin">string</span> <span class="token string">\`json:&quot;source&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> HTTPStatusError <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	StatusCode <span class="token builtin">int</span></span>
<span class="line">	Status     <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>err <span class="token operator">*</span>HTTPStatusError<span class="token punctuation">)</span> <span class="token function">Error</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">&quot;сервис приоритетов вернул %s&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">.</span>Status<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>client <span class="token operator">*</span>Client<span class="token punctuation">)</span> <span class="token function">Suggest</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> title <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>PriorityHint<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> hint PriorityHint</span>
<span class="line"></span>
<span class="line">	response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span>resty<span class="token punctuation">.</span><span class="token function">R</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">		<span class="token function">SetContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">		<span class="token function">SetQueryParam</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">,</span> title<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">		<span class="token function">SetResult</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>hint<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">		<span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;выполнить запрос подсказки: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> response<span class="token punctuation">.</span><span class="token function">IsError</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>HTTPStatusError<span class="token punctuation">{</span></span>
<span class="line">			StatusCode<span class="token punctuation">:</span> response<span class="token punctuation">.</span><span class="token function">StatusCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">			Status<span class="token punctuation">:</span>     response<span class="token punctuation">.</span><span class="token function">Status</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span>response<span class="token punctuation">.</span><span class="token function">IsSuccess</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>HTTPStatusError<span class="token punctuation">{</span></span>
<span class="line">			StatusCode<span class="token punctuation">:</span> response<span class="token punctuation">.</span><span class="token function">StatusCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">			Status<span class="token punctuation">:</span>     response<span class="token punctuation">.</span><span class="token function">Status</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> hint<span class="token punctuation">.</span>Priority <span class="token operator">&lt;</span> <span class="token number">1</span> <span class="token operator">||</span> hint<span class="token punctuation">.</span>Priority <span class="token operator">&gt;</span> <span class="token number">5</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;некорректный приоритет внешнего сервиса: %d&quot;</span><span class="token punctuation">,</span> hint<span class="token punctuation">.</span>Priority<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> hint<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>response.IsError()</code> покрывает ответы <code>400–599</code>. Дополнительная проверка <code>!response.IsSuccess()</code> защищает контракт «принимаем только 2xx»: например, <code>304 Not Modified</code> — не ошибка Resty, но не является JSON-подсказкой в нашем API.</p><p>Resty управляет response body внутри <code>Execute</code>, поэтому вручную писать <code>defer response.Body.Close()</code> здесь не нужно. Но это не отменяет правило из предыдущей главы: в чистом <code>net/http</code> body всегда закрывает вызывающий код.</p><h2 id="строгость-json-и-размер-ответа" tabindex="-1"><a class="header-anchor" href="#строгость-json-и-размер-ответа"><span>Строгость JSON и размер ответа</span></a></h2><p><code>SetResult</code> удобен, но его стандартная JSON-десериализация не заменяет полный контроль предыдущей главы. Если внешний контракт требует запрета неизвестных полей, строгой проверки одного JSON-значения или своего лимита body, оставьте реализацию на <code>net/http</code> либо настройте отдельную обработку и покройте её тестами.</p><p>Для простой, доверенной интеграции <code>SetResult</code> делает код короче. Для критичной границы — платежи, безопасность, нестабильный внешний контракт — предпочтительнее явно читать и ограничивать body, как в главе про <code>http.Client</code>.</p><h2 id="ограниченныи-retry" tabindex="-1"><a class="header-anchor" href="#ограниченныи-retry"><span>Ограниченный retry</span></a></h2><p>Resty поддерживает retry с backoff. Это не повод повторять каждый запрос. В нашем случае допустим пример только для идемпотентного <code>GET</code>, когда сервер вернул временный <code>503 Service Unavailable</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">client <span class="token operator">:=</span> resty<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetBaseURL</span><span class="token punctuation">(</span>baseURL<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetRetryCount</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetRetryWaitTime</span><span class="token punctuation">(</span><span class="token number">100</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Millisecond<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">SetRetryMaxWaitTime</span><span class="token punctuation">(</span><span class="token number">500</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Millisecond<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">	<span class="token function">AddRetryCondition</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>response <span class="token operator">*</span>resty<span class="token punctuation">.</span>Response<span class="token punctuation">,</span> err <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> err <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> response<span class="token punctuation">.</span><span class="token function">StatusCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">==</span> http<span class="token punctuation">.</span>StatusServiceUnavailable</span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Это означает максимум три попытки: первоначальная и две повторные. Resty применяет backoff с jitter между попытками.</p><p>Не применяйте такой retry автоматически к <code>POST /tasks</code>: повтор может создать дубликат. Для безопасных повторов нужны идемпотентность, контекст, ограничение попыток, политика статусов и наблюдаемость. В базовой реализации <code>Suggest</code> retry выключен; пример нужен, чтобы понимать настройку, а не включать её без причины.</p><h2 id="hooks-и-структурированное-логирование" tabindex="-1"><a class="header-anchor" href="#hooks-и-структурированное-логирование"><span>Hooks и структурированное логирование</span></a></h2><p>Resty позволяет добавить hook после получения ответа:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">addAccessLog</span><span class="token punctuation">(</span>client <span class="token operator">*</span>resty<span class="token punctuation">.</span>Client<span class="token punctuation">,</span> logger <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	client<span class="token punctuation">.</span><span class="token function">OnAfterResponse</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span><span class="token boolean">_</span> <span class="token operator">*</span>resty<span class="token punctuation">.</span>Client<span class="token punctuation">,</span> response <span class="token operator">*</span>resty<span class="token punctuation">.</span>Response<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">		logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span></span>
<span class="line">			<span class="token string">&quot;внешний HTTP-запрос завершён&quot;</span><span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;method&quot;</span><span class="token punctuation">,</span> response<span class="token punctuation">.</span>Request<span class="token punctuation">.</span>Method<span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;url&quot;</span><span class="token punctuation">,</span> response<span class="token punctuation">.</span>Request<span class="token punctuation">.</span>URL<span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;status&quot;</span><span class="token punctuation">,</span> response<span class="token punctuation">.</span><span class="token function">StatusCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">			<span class="token string">&quot;duration&quot;</span><span class="token punctuation">,</span> response<span class="token punctuation">.</span><span class="token function">Time</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">		<span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Hook полезен для наблюдаемости, но не должен выводить <code>Authorization</code>, cookies или response body. Он также не заменяет обработку <code>err</code>: при сетевой ошибке response может отсутствовать, поэтому логирование таких случаев делают на границе вызова или через <code>OnError</code> с аккуратной фильтрацией данных.</p><h2 id="тестирование-через-httptest-server" tabindex="-1"><a class="header-anchor" href="#тестирование-через-httptest-server"><span>Тестирование через <code>httptest.Server</code></span></a></h2><p>Resty-клиент проверяют так же, как версию на <code>http.Client</code>: тестовый сервер проверяет исходный request и отдаёт контролируемый ответ.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestSuggest</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	server <span class="token operator">:=</span> httptest<span class="token punctuation">.</span><span class="token function">NewServer</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span><span class="token function">HandlerFunc</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">if</span> r<span class="token punctuation">.</span>Method <span class="token operator">!=</span> http<span class="token punctuation">.</span>MethodGet <span class="token punctuation">{</span></span>
<span class="line">			t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;method = %s, ожидался GET&quot;</span><span class="token punctuation">,</span> r<span class="token punctuation">.</span>Method<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">		<span class="token keyword">if</span> r<span class="token punctuation">.</span>URL<span class="token punctuation">.</span>Path <span class="token operator">!=</span> <span class="token string">&quot;/v1/suggest&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">			t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;path = %q&quot;</span><span class="token punctuation">,</span> r<span class="token punctuation">.</span>URL<span class="token punctuation">.</span>Path<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">		<span class="token keyword">if</span> got <span class="token operator">:=</span> r<span class="token punctuation">.</span>URL<span class="token punctuation">.</span><span class="token function">Query</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> got <span class="token operator">!=</span> <span class="token string">&quot;Купить молоко&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">			t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;title = %q&quot;</span><span class="token punctuation">,</span> got<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">		w<span class="token punctuation">.</span><span class="token function">Header</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Content-Type&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		fmt<span class="token punctuation">.</span><span class="token function">Fprint</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> <span class="token string">\`{&quot;priority&quot;:3,&quot;source&quot;:&quot;title-rules&quot;}\`</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> server<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	client <span class="token operator">:=</span> <span class="token function">New</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>URL<span class="token punctuation">,</span> server<span class="token punctuation">.</span><span class="token function">Client</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>Transport<span class="token punctuation">)</span></span>
<span class="line">	hint<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">Suggest</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;Suggest вернул ошибку: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> hint <span class="token operator">!=</span> <span class="token punctuation">(</span>PriorityHint<span class="token punctuation">{</span>Priority<span class="token punctuation">:</span> <span class="token number">3</span><span class="token punctuation">,</span> Source<span class="token punctuation">:</span> <span class="token string">&quot;title-rules&quot;</span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;hint = %+v&quot;</span><span class="token punctuation">,</span> hint<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Тесты также должны покрыть <code>429</code>, некорректный JSON и отменённый context. Для отмены отмените context до вызова — это детерминированно и не требует <code>time.Sleep</code>.</p><h2 id="когда-выбрать-http-client-а-когда-resty" tabindex="-1"><a class="header-anchor" href="#когда-выбрать-http-client-а-когда-resty"><span>Когда выбрать <code>http.Client</code>, а когда Resty</span></a></h2><table><thead><tr><th>Ситуация</th><th>Выбор</th></tr></thead><tbody><tr><td>Небольшой клиент, нужен минимальный набор зависимостей и полный контроль body</td><td><code>net/http</code></td></tr><tr><td>Обычные JSON API, много одинаковых headers/query/response DTO</td><td>Resty</td></tr><tr><td>Строгий контроль лимитов, формата тела и потокового чтения</td><td><code>net/http</code></td></tr><tr><td>Нужны готовые retry hooks, base URL и компактный код</td><td>Resty с явной политикой retry</td></tr></tbody></table><p>В итоговом Task Manager можно оставить реализацию на <code>http.Client</code> или заменить её на Resty: interface <code>PrioritySuggester</code> и service при этом не меняются. В этом курсе финальную реализацию клиента подсказок строим на Resty, а фундаментальная глава про стандартный клиент остаётся обязательной.</p><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="считать-response-iserror-единственнои-проверкои" tabindex="-1"><a class="header-anchor" href="#считать-response-iserror-единственнои-проверкои"><span>Считать <code>response.IsError()</code> единственной проверкой</span></a></h3><p><code>IsError()</code> не считает <code>3xx</code> ошибкой. Если контракт принимает только JSON-ответы <code>2xx</code>, после неё обязательно проверяйте <code>response.IsSuccess()</code>.</p><h3 id="включить-retry-для-всех-методов" tabindex="-1"><a class="header-anchor" href="#включить-retry-для-всех-методов"><span>Включить retry для всех методов</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">client<span class="token punctuation">.</span><span class="token function">SetRetryCount</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">AddRetryAfterErrorCondition</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Такая глобальная настройка может повторить опасные <code>POST</code>, <code>PATCH</code> и <code>DELETE</code>. Ограничивайте retry по методу и статусу либо назначайте его точечно конкретному GET-запросу.</p><h3 id="привязать-service-к-resty" tabindex="-1"><a class="header-anchor" href="#привязать-service-к-resty"><span>Привязать service к Resty</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> TaskService <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	priorities <span class="token operator">*</span>resty<span class="token punctuation">.</span>Client</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Service должен получать интерфейс <code>PrioritySuggester</code>; Resty — деталь реализации инфраструктурного пакета.</p><h3 id="считать-setresult-достаточнои-валидациеи" tabindex="-1"><a class="header-anchor" href="#считать-setresult-достаточнои-валидациеи"><span>Считать SetResult достаточной валидацией</span></a></h3><p>JSON может быть синтаксически корректным, но содержать недопустимый priority. Всегда проверяйте данные внешнего сервиса по собственному контракту.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>Task Manager использует Resty для компактной реализации внешнего HTTP-клиента, сохраняя правила HTTP и независимость service. Далее настроим конфигурацию и жизненный цикл приложения: переменные окружения, проверку настроек, graceful shutdown и health-check.</p>`,81)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};